-- Training initial schema. UUIDs are generated by the client for every mutable row.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, start_weight_kg numeric, program_start_date date, program_length_weeks int not null default 12, created_at timestamptz not null default now());
create table public.exercises (id uuid primary key, name text not null, muscle_group text not null, equipment text not null default 'dumbbell', musclewiki_slug text, is_time_based boolean not null default false);
create table public.program_days (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, weekday int not null check(weekday between 1 and 5), focus text not null, cue text);
create table public.program_exercises (id uuid primary key, program_day_id uuid not null references public.program_days(id) on delete cascade, exercise_id uuid not null references public.exercises(id), order_index int not null, target_sets int not null, target_reps text not null, prescribed_weight_kg numeric, prescribed_reps int not null);
create table public.sessions (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, session_date date not null, program_day_id uuid references public.program_days(id), week_number int, burn_rating int, notes text, cardio_done boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.set_logs (id uuid primary key, session_id uuid not null references public.sessions(id) on delete cascade, exercise_id uuid not null references public.exercises(id), set_number int not null, weight_kg numeric, reps int not null, completed_at timestamptz not null default now());
create table public.body_metrics (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, recorded_at date not null, weight_kg numeric, source text not null default 'manual', unique(user_id,recorded_at,source));
create table public.cardio_sessions (id uuid primary key, user_id uuid not null references public.profiles(id) on delete cascade, session_id uuid references public.sessions(id) on delete set null, started_at timestamptz, duration_min numeric, distance_km numeric, avg_hr int, avg_pace text, steps int, source text not null default 'health_connect');

alter table public.profiles enable row level security; alter table public.exercises enable row level security; alter table public.program_days enable row level security; alter table public.program_exercises enable row level security; alter table public.sessions enable row level security; alter table public.set_logs enable row level security; alter table public.body_metrics enable row level security; alter table public.cardio_sessions enable row level security;
create policy "users manage own profile" on public.profiles for all using (auth.uid()=id) with check(auth.uid()=id);
create policy "authenticated read exercise catalogue" on public.exercises for select to authenticated using (true);
create policy "users manage own program days" on public.program_days for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users manage own program exercises" on public.program_exercises for all using(exists(select 1 from public.program_days d where d.id=program_day_id and d.user_id=auth.uid())) with check(exists(select 1 from public.program_days d where d.id=program_day_id and d.user_id=auth.uid()));
create policy "users manage own sessions" on public.sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users manage own set logs" on public.set_logs for all using(exists(select 1 from public.sessions s where s.id=session_id and s.user_id=auth.uid())) with check(exists(select 1 from public.sessions s where s.id=session_id and s.user_id=auth.uid()));
create policy "users manage own metrics" on public.body_metrics for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users manage own cardio" on public.cardio_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
